import sys


def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    get = sums.get
    for line in data[1:]:
        if not line:
            continue
        _, c, v = line.split(b',', 2)
        if v[-3:-2] == b'.' and v[-2:].isdigit() and v[:-3].isdigit():
            cents = int(v[:-3]) * 100 + int(v[-2:])
        else:
            cents = round(float(v) * 100)
        sums[c] = get(c, 0) + cents
    out = []
    for c in sorted(sums):
        s = sums[c]
        sign = '-' if s < 0 else ''
        d, r = divmod(abs(s), 100)
        out.append(c.decode() + ',' + sign + '%d.%02d' % (d, r))
    sys.stdout.write('\n'.join(out) + ('\n' if out else ''))


main()
